Flask 3.1. Handlers return render_template(...) WITH the status (Flask does not set it). Views: abort(404) for an unknown id/slug (a <int:id> converter already 404s on a wrong type). FLASK_DEBUG turns on the interactive Werkzeug debugger (stack traces, console) so the startup guard below refuses it in production (SEC-007). Call register_errors(app) from create_app(); extends base.html from the headers recipe.
### file: app/errors.py
import os

from flask import Flask, abort, render_template, request
from sqlalchemy.exc import OperationalError, TimeoutError as PoolTimeout
from werkzeug.exceptions import HTTPException

# RTE-004: paths retired with no successor answer 410, not 404.
RETIRED_PATHS = {"/old-pricing"}
# RTE-007: dependency failures are 503, never 404 and never a 200 shell. Add your upstream errors here.
UNAVAILABLE = (OperationalError, PoolTimeout)


def register_errors(app: Flask) -> None:
    if os.environ.get("DEPLOY_ENV") == "production" and app.debug:
        raise RuntimeError("FLASK_DEBUG must be off in production (SEC-007)")

    @app.before_request
    def gone():
        if request.path in RETIRED_PATHS:
            abort(410)

    @app.errorhandler(HTTPException)  # 404, 405, 410, 429, CSRFError (400)... keeps e.g. Allow / Retry-After
    def http_error(e: HTTPException):
        code = e.code or 500
        resp = e.get_response()
        resp.data = render_template("error.html", code=code, title=e.name)
        resp.content_type = "text/html; charset=utf-8"
        return resp

    def unavailable(e: Exception):
        app.logger.error("dependency unavailable: %s", type(e).__name__)
        resp = app.make_response((render_template("error.html", code=503, title="Service Unavailable"), 503))
        resp.headers["Retry-After"] = "30"
        resp.headers["Cache-Control"] = "no-store"
        return resp

    for exc in UNAVAILABLE:
        app.register_error_handler(exc, unavailable)

    @app.errorhandler(Exception)  # non-HTTP errors only: HTTPException has the more specific handler above
    def server_error(e: Exception):
        app.logger.exception("unhandled error")  # the log gets the trace, the visitor never does
        resp = app.make_response((render_template("error.html", code=500, title="Server Error"), 500))
        resp.headers["Cache-Control"] = "no-store"
        return resp
