import os

import requests
from flask import Blueprint, current_app, redirect, render_template, request, url_for
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from flask_wtf.csrf import CSRFProtect

csrf = CSRFProtect()  # SEC-024: rejects every POST without a valid csrf_token (400)
limiter = Limiter(
    get_remote_address,
    storage_uri=os.environ.get("RATELIMIT_STORAGE_URI", "memory://"),
    headers_enabled=True,  # Retry-After on the 429
)
contact_bp = Blueprint("contact", __name__)


def init_contact(app):
    app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]
    app.config.update(
        SESSION_COOKIE_SECURE=os.environ.get("DEPLOY_ENV") == "production",  # plain http in local dev
        SESSION_COOKIE_SAMESITE="Lax",
    )
    csrf.init_app(app)
    limiter.init_app(app)
    app.register_blueprint(contact_bp)


def validate(form):
    errors = {}
    if not 1 <= len(form["name"]) <= 100:
        errors["name"] = "Please enter your name (max 100 characters)."
    if not (3 <= len(form["email"]) <= 254 and "@" in form["email"]):
        errors["email"] = "Please enter a valid email address."
    if not 1 <= len(form["message"]) <= 5000:
        errors["message"] = "Please enter a message (max 5000 characters)."
    return errors


@contact_bp.get("/contact")
def contact_form():
    return render_template("contact.html", form={}, errors={})


@contact_bp.post("/contact")
@limiter.limit("5 per 10 minutes")  # SEC-054: the 6th POST in the window is answered 429
def contact_submit():
    if request.form.get("hp_company"):  # SEC-055 honeypot filled: same response, no side effect
        return redirect(url_for("contact.thanks"), code=303)
    form = {k: (request.form.get(k) or "").strip() for k in ("name", "email", "message")}
    errors = validate(form)
    if errors:
        return render_template("contact.html", form=form, errors=errors), 422
    try:
        # REPLACE this call with your destination (CRM API, email provider, DB insert) and keep the checks.
        r = requests.post(os.environ["FORM_WEBHOOK_URL"], json=form, timeout=8)
        r.raise_for_status()  # RES-008: a 4xx/5xx from the destination is a failed delivery
    except requests.RequestException as exc:
        current_app.logger.error("contact delivery failed: %s", type(exc).__name__)
        errors = {"form": "We could not send your message. Please try again later."}
        return render_template("contact.html", form=form, errors=errors), 502
    return redirect(url_for("contact.thanks"), code=303)  # POST/redirect/GET, works without JavaScript


@contact_bp.get("/contact/thanks")
def thanks():
    return render_template("contact_thanks.html")
