import os
from xml.sax.saxutils import escape

from flask import Blueprint, Flask, Response, abort

seo_bp = Blueprint("seo", __name__)
MAX_URLS = 50_000  # IDX-004: above this, split into a sitemap index


def is_production() -> bool:
    return os.environ.get("DEPLOY_ENV") == "production"


def site_url() -> str:
    return os.environ["SITE_URL"].rstrip("/")  # e.g. https://example.com, same host/scheme as the canonical tags


def indexable_paths() -> list[str]:
    # Replace: exactly the public pages that return 200, are canonical and not noindex.
    # Use the same trailing-slash policy as the canonical tags.
    return ["/", "/about", "/contact"]


@seo_bp.get("/robots.txt")
def robots():
    if is_production():
        body = (
            "User-agent: *\nAllow: /\n"
            "Disallow: /api/\nDisallow: /admin/\n"  # never disallow /static/ or other CSS/JS/image paths
            f"\nSitemap: {site_url()}/sitemap.xml\n"
        )
    else:
        body = "User-agent: *\nDisallow: /\n"  # no Sitemap line outside production
    return Response(body, mimetype="text/plain")


@seo_bp.get("/sitemap.xml")
def sitemap():
    if not is_production():
        abort(404)
    urls = list(dict.fromkeys(site_url() + p for p in indexable_paths()))  # unique, order kept
    if len(urls) > MAX_URLS:
        raise RuntimeError("more than 50,000 URLs: write a sitemap index")
    entries = "".join(f"<url><loc>{escape(u)}</loc></url>\n" for u in urls)  # XML-escape every value
    xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + entries + "</urlset>\n"
    )
    return Response(xml, mimetype="application/xml")


def init_seo(app: Flask) -> None:
    app.register_blueprint(seo_bp)

    @app.after_request  # every response, including static files and error pages
    def noindex_outside_production(resp):
        if not is_production():
            resp.headers["X-Robots-Tag"] = "noindex, nofollow"
        return resp
